from __future__ import annotations

from pydantic import Field
from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, SdkBaseModel


class TokenUsage(SdkBaseModel):
    input_tokens: Optional[int] = Field(default=UNSET, alias="inputTokens")
    """Non-cached input tokens. Matches Anthropic's ``input_tokens`` semantic (does not include cached or cache-creation
    tokens)."""

    output_tokens: Optional[int] = Field(default=UNSET, alias="outputTokens")
    """Output tokens generated by the model."""

    cache_read_input_tokens: Optional[int] = Field(default=UNSET, alias="cacheReadInputTokens")
    """Input tokens served from cache (cache hit)."""

    cache_creation_input_tokens: Optional[int] = Field(default=UNSET, alias="cacheCreationInputTokens")
    """Input tokens written to cache on this request (Anthropic prompt caching)."""

    reasoning_output_tokens: Optional[int] = Field(default=UNSET, alias="reasoningOutputTokens")
    """Reasoning tokens emitted by reasoning models (o1/o3, Claude extended thinking)."""


class TokenUsageDict(TypedDict):
    input_tokens: NotRequired[int]
    output_tokens: NotRequired[int]
    cache_read_input_tokens: NotRequired[int]
    cache_creation_input_tokens: NotRequired[int]
    reasoning_output_tokens: NotRequired[int]
